const inputData = $input.all();
let rawData = [];

// 1. Descubrimiento de datos
if (Array.isArray(inputData) && inputData.length > 0) {
    rawData = Array.isArray(inputData[0].json) ? inputData[0].json : inputData.map(item => item.json);
}

// 2. Mapeo de Columnas
const columnMapping = {
    '__EMPTY': 'Tipo',
    '__EMPTY_1': 'Punto de Venta',
    '__EMPTY_2': 'Número Desde',
    '__EMPTY_6': 'Nro. Doc. Emisor',
    '__EMPTY_7': 'Denominación Emisor',
    '__EMPTY_10': 'Tipo Cambio',
    '__EMPTY_11': 'Moneda',
    '__EMPTY_27': 'Total IVA',
    '__EMPTY_28': 'Imp. Total'
};

// Buscar dinámicamente la columna de Fecha
const firstRow = rawData[0] || {};
const dateKey = Object.keys(firstRow).find(key => key.includes('Mis Comprobantes Recibidos'));
if (dateKey) columnMapping[dateKey] = 'Fecha';

// 3. Helper para números (Maneja strings con formato AR o números directos)
const parseNumber = (val) => {
    if (val === null || val === undefined || val === '') return 0;
    if (typeof val === 'number') return val;
    let cleanVal = val.toString().replace(/\./g, '').replace(',', '.');
    return parseFloat(cleanVal) || 0;
};

// 4. Procesamiento Multimoneda
const result = rawData
    .slice(1) 
    .flatMap(row => {
        const newRow = {};

        for (const [oldKey, newKey] of Object.entries(columnMapping)) {
            newRow[newKey] = row[oldKey] ?? null;
        }

        // FIX B: Descartar filas vacías (cola del Excel de ARCA sin datos reales).
        // Si no hay Nro. Doc. Emisor real, no es un comprobante: se elimina.
        const emisor = newRow['Nro. Doc. Emisor'];
        if (emisor === null || emisor === undefined || emisor.toString().trim() === '') {
            return [];
        }

        const tc = parseNumber(newRow['Tipo Cambio']);
        const moneda = (newRow['Moneda'] || '').trim();
        const impTotalOriginal = parseNumber(newRow['Imp. Total']);
        const ivaTotalOriginal = parseNumber(newRow['Total IVA']);

        // LÓGICA UNIVERSAL: 
        // Si la moneda NO es pesos ($) y el Tipo de Cambio es mayor a 1, convertimos.
        if (moneda !== '$' && tc > 1) {
            newRow['Imp. Total'] = Math.round(impTotalOriginal * tc * 100) / 100;
            newRow['Total IVA'] = Math.round(ivaTotalOriginal * tc * 100) / 100;
            newRow['Observaciones_Moneda'] = `Convertido de ${moneda} a ARS (TC: ${tc})`;
        } else {
            // Si ya está en pesos o no hay TC válido, mantenemos el valor original
            newRow['Imp. Total'] = impTotalOriginal;
            newRow['Total IVA'] = ivaTotalOriginal;
        }

        return { json: newRow };
    });

return result;

// ============================================================
// CRUCE ARCA - Comprobantes (SIGNOS, TOLERANCIA 0.03 & IVA TOTAL)
// v2 - FIX A: ignora filas vacías (Nro. Doc. Emisor null/vacío)
// ============================================================

const toNumber = (val) => {
  if (val === null || val === undefined || val === '') return 0;
  const num = typeof val === 'number' ? val : parseFloat(val);
  return isNaN(num) ? 0 : Math.round(num * 100) / 100;
};

// 1. DICCIONARIO DE EQUIVALENCIAS
const arcaToNorm = {
  "1": "FCA", "2": "NDA", "3": "NCA", "4": "RCA", "6": "FCB", "7": "NDB", "8": "NCB", "9": "RCB", "11": "FCC", "12": "NDC", "13": "NCC", "15": "RCC",
  "81": "TKA", "82": "TKB", "109": "TKC", "111": "TKC", "195": "FCT", "196": "NDT", "197": "NCT",
  "201": "FCA", "202": "NDA", "203": "NCA", "206": "FCB", "207": "NDB", "208": "NCB", "211": "FCC", "212": "NDC", "213": "NCC"
};

const ivaToNorm = {
  "FC A": "FCA", "ND A": "NDA", "NC A": "NCA", "RC A": "RCA", "FC B": "FCB", "ND B": "NDB", "NC B": "NCB", "RC B": "RCB", "FC C": "FCC", "ND C": "NDC", "NC C": "NCC", "RC C": "RCC",
  "TK A": "TKA", "TK B": "TKB", "TK C": "TKC", "FT T": "FCT", "ND T": "NDT", "CT T": "NCT", "FC": "FCA", "NC": "NCA", "ND": "NDA"
};

const normalizeType = (tc, letra, source) => {
  if (source === 'ARCA') {
    const code = tc.toString().split(' ')[0];
    return arcaToNorm[code] || tc.toString();
  } else {
    const key = `${tc} ${letra || ''}`.trim();
    return ivaToNorm[key] || ivaToNorm[tc] || key.replace(/\s/g, '');
  }
};

const allItems = $input.all();
const ivaCompras = [];
const arcaRecords = [];

// 2. SEPARAR Y NORMALIZAR DATOS
for (const item of allItems) {
  const data = item.json;
  if (data.TC !== undefined && data.CUIT) {
    const tipoNorm = normalizeType(data.TC, data.Letra, 'IVA');

    // NUEVO: Sumamos todas las alícuotas de IVA del sistema para obtener el Total
    const ivaTotalSist = toNumber(data['IVA 21%']) + toNumber(data['IVA 10.5%']) + toNumber(data['IVA 27%']) + toNumber(data['IVA 5%']) + toNumber(data['IVA 2.5%']);

    ivaCompras.push({
      ...data,
      _tipoNorm: tipoNorm,
      _importe: toNumber(data['Total Comprobante']),
      _ivaTotal: ivaTotalSist, // Guardamos el IVA calculado
      _cuit: data.CUIT.toString().replace(/\D/g,''),
      matched: false
    });
  } else if (data['Nro. Doc. Emisor'] !== undefined && data['Nro. Doc. Emisor'] !== null && data['Nro. Doc. Emisor'].toString().trim() !== '') {
    const tipoNorm = normalizeType(data['Tipo'], null, 'ARCA');
    arcaRecords.push({
      ...data,
      _tipoNorm: tipoNorm,
      _importe: toNumber(data['Imp. Total']),
      _ivaTotal: toNumber(data['Total IVA']), // Capturamos el IVA de ARCA
      _cuit: data['Nro. Doc. Emisor'].toString().replace(/\D/g,''),
      _pv: data['Punto de Venta'],
      _nro: data['Número Desde'],
      matched: false
    });
  }
}

const results = [];

// 3. CRUCE LÓGICO
for (const comp of ivaCompras) {
  const razonSocial = comp['Razón Social'] || comp['Nombre o Razón Social'] || "N/A";

  // Intento 1: Match Exacto (Signos y Tolerancia 0.03)
  let match = arcaRecords.find(a => 
    !a.matched && a._cuit === comp._cuit && a._tipoNorm === comp._tipoNorm &&
    a._pv == comp['Pto. Vta.'] && a._nro == comp['Nro. Desde'] &&
    Math.abs(Math.abs(a._importe) - Math.abs(comp._importe)) <= 0.031
  );

  if (match) {
    match.matched = true;
    results.push({
      json: {
        Fecha: comp.Fecha, Razon_Social: razonSocial, CUIT: comp.CUIT,
        Comprobante: `${comp.TC}${comp.Letra} ${comp['Pto. Vta.']}-${comp['Nro. Desde']}`,
        Importe: comp._importe, 
        IVA_Total: comp._ivaTotal, // PASAMOS EL IVA
        Estado_Cruce: "Encontrados sin diferencias", Observaciones: "Coincidencia exacta"
      }
    });
    continue;
  }

  // Intento 2: Match Parcial
  match = arcaRecords.find(a => !a.matched && a._cuit === comp._cuit && Math.abs(Math.abs(a._importe) - Math.abs(comp._importe)) <= 0.031);
  if (match) {
    match.matched = true;
    results.push({
      json: {
        Fecha: comp.Fecha, Razon_Social: razonSocial, CUIT: comp.CUIT,
        Comprobante: `Sist: ${comp.TC}${comp.Letra} ${comp['Pto. Vta.']}-${comp['Nro. Desde']} / ARCA: ${match._pv}-${match._nro}`,
        Importe: comp._importe, 
        IVA_Total: comp._ivaTotal, // PASAMOS EL IVA
        Estado_Cruce: "Encontrados con diferencias",
        Observaciones: `Diferencia en Tipo (${comp._tipoNorm} vs ${match._tipoNorm}) o Numeración`
      }
    });
    continue;
  }

  // Falta en ARCA
  results.push({
    json: {
      Fecha: comp.Fecha, Razon_Social: razonSocial, CUIT: comp.CUIT,
      Comprobante: `${comp.TC}${comp.Letra} ${comp['Pto. Vta.']}-${comp['Nro. Desde']}`,
      Importe: comp._importe, 
      IVA_Total: comp._ivaTotal, // PASAMOS EL IVA
      Estado_Cruce: "Falta en ARCA", Observaciones: "No se encontró el CUIT con ese importe"
    }
  });
}

// 4. HUÉRFANOS ARCA
for (const a of arcaRecords) {
  if (!a.matched) {
    results.push({
      json: {
        Fecha: a.Fecha, Razon_Social: a['Denominación Emisor'], CUIT: a._cuit,
        Comprobante: `${a._tipoNorm} ${a._pv}-${a._nro}`, 
        Importe: a._importe, 
        IVA_Total: a._ivaTotal, // PASAMOS EL IVA
        Estado_Cruce: "Falta en IVA Compras", Observaciones: "Registrado en AFIP pero no localmente"
      }
    });
  }
}

return results;

// ============================================================
// IVA COMPRA 2 - FILTRO - VERSION 1.3
// Purpose: Extract perceptions preserving decimal format from Excel
// Last Updated: 2026-01-25
// Fix: Properly handle Excel decimal format (dot as decimal separator)
// ============================================================

function formatDate(value) {
  if (!value) return null;

  if (typeof value === 'number' || (typeof value === 'string' && !isNaN(value) && !value.includes('/'))) {
    const date = new Date(Math.round((parseFloat(value) - 25569) * 86400 * 1000));
    return date.toISOString().split('T')[0];
  }

  if (typeof value === 'string' && value.includes('/')) {
    const parts = value.split('/');
    if (parts.length === 3) {
      const date = new Date(parts[2], parts[1] - 1, parts[0]); 
      return date.toISOString().split('T')[0];
    }
  }

  return value;
}

// Fixed normalization - Excel uses dot as decimal separator
function normalizeAmount(value) {
  if (value === undefined || value === null || value === '') return 0;

  // If already a number, just round it
  if (typeof value === 'number') {
    return Math.round(value * 100) / 100;
  }

  // If string, parse it directly (Excel exports use dot as decimal)
  const numValue = parseFloat(value);
  return isNaN(numValue) ? 0 : Math.round(numValue * 100) / 100;
}

const items = $input.all();

return items.flatMap(item => {
  const data = item.json;

  const fechaStr = (data["Fecha"] || "").toString().toUpperCase();
  if (fechaStr.includes("TOTAL")) return [];

  const headerDate   = "Fecha";
  const headerNumber = "Nro. Desde";
  const headerCUIT   = "CUIT";
  const headerPerc   = "Percepciones IVA";

  const valPerc = data[headerPerc];
  const numPerc = normalizeAmount(valPerc);

  if (!isNaN(numPerc) && numPerc !== 0) {
    return {
      json: {
        "Fecha": formatDate(data[headerDate]),
        "Nro. Desde": data[headerNumber],
        "CUIT": data[headerCUIT],
        "Percepciones IVA": numPerc,
        "Razón Social": data["Razón Social"] || data["Razon Social"] || "N/A"
      }
    };
  }

  return [];
});

// 1. HELPER: Función para formatear fechas (OBLIGATORIO en cada nodo de código)
function formatDate(value) {
  if (!value) return null;

  // Caso: Número de serie de Excel (ej: 45840)
  if (typeof value === 'number' || (typeof value === 'string' && !isNaN(value) && !value.includes('/'))) {
    const date = new Date(Math.round((parseFloat(value) - 25569) * 86400 * 1000));
    return date.toISOString().split('T')[0]; // Retorna YYYY-MM-DD
  }

  // Caso: Fecha en formato texto (ej: "01/07/2025")
  if (typeof value === 'string' && value.includes('/')) {
    const parts = value.split('/');
    if (parts.length === 3) {
      const date = new Date(parts[2], parts[1] - 1, parts[0]); 
      return date.toISOString().split('T')[0];
    }
  }

  return value;
}

// 2. LÓGICA PRINCIPAL
const items = $input.all();

return items.flatMap(item => {
  const data = item.json;

  // --- FILTRO 1: Ignorar filas de totales ---
  const fechaStr = (data["Fecha"] || "").toString().toUpperCase();
  if (fechaStr.includes("TOTAL")) return [];

  // --- FILTRO 2: Solo comprobantes tipo 'CR' (Retenciones en Ventas) ---
  if (data["TC"] === 'CR') {
    const valAmount = data["Total Comprobante"];

    // Transformación: Invertir el signo (de negativo a positivo)
    const numericAmount = (typeof valAmount === 'number') ? valAmount : parseFloat(valAmount || 0);
    const finalAmount = Math.abs(numericAmount); // Usamos Math.abs para asegurar que sea positivo

    // --- SALIDA ---
    return {
      json: {
        "Fecha": formatDate(data["Fecha"]),
        "TC": data["TC"],
        "CUIT": data["CUIT"],
        "Total Comprobante": finalAmount,
        // Captura Razón Social con soporte para variaciones de encabezado
        "Razón Social": data["Razón Social"] || data["Razon Social"] || "N/A"
      }
    };
  }

  // Descartar si no es 'CR'
  return [];
});

// ============================================================
// MIS RETENCIONES-FILTRO - VERSION 1.3
// Purpose: Extract data preserving decimal format from Excel
// Last Updated: 2026-01-25
// Fix: Properly handle Excel decimal format (dot as decimal separator)
// ============================================================

function formatDate(value) {
  if (!value) return null;

  if (typeof value === 'number' || (typeof value === 'string' && !isNaN(value) && !value.includes('/'))) {
    const date = new Date(Math.round((parseFloat(value) - 25569) * 86400 * 1000));
    return date.toISOString().split('T')[0];
  }

  if (typeof value === 'string' && value.includes('/')) {
    const parts = value.split('/');
    if (parts.length === 3) {
      const date = new Date(parts[2], parts[1] - 1, parts[0]); 
      return date.toISOString().split('T')[0];
    }
  }

  return value;
}

// Fixed normalization - Excel uses dot as decimal separator
function normalizeAmount(value) {
  if (value === undefined || value === null || value === '') return 0;

  // If already a number, just round it
  if (typeof value === 'number') {
    return Math.round(value * 100) / 100;
  }

  // If string, parse it directly (Excel exports use dot as decimal)
  const numValue = parseFloat(value);
  return isNaN(numValue) ? 0 : Math.round(numValue * 100) / 100;
}

const items = $input.all();

const results = items.map(item => {
  return {
    json: {
      "CUIT Agente Ret./Perc.": item.json["CUIT Agente Ret./Perc."],
      "Razón Social": item.json["Denominación o Razón Social"],
      "Fecha Ret./Perc.": formatDate(item.json["Fecha Ret./Perc."]),
      "Descripción Operación": item.json["Descripción Operación"],
      "Importe Ret./Perc.": normalizeAmount(item.json["Importe Ret./Perc."]),
      "Número Comprobante": item.json["Número Comprobante"]
    }
  };
});

return results;

// ============================================================
// COMPARE 2 - VERSION 1.4
// Purpose: Cross-check with tolerance and show ALL matches
// Last Updated: 2026-01-25
// Changes: Show both perfect matches AND matches with differences
// ============================================================

// --- 1. HELPER FUNCTIONS ---

const normalizeAmount = (val) => {
  if (val === undefined || val === null || val === '') return 0;
  let num = typeof val === 'string' ? parseFloat(val.replace(',', '.')) : val;
  return Math.round(num * 100) / 100;
};

const normalizeDate = (val) => {
  if (!val) return '';
  if (typeof val === 'string' && val.includes('T')) return val.split('T')[0];
  return val;
};

const normalizeCUIT = (val) => {
  if (!val) return '';
  return val.toString().replace(/-/g, '').trim();
};

const getStandardInvoice = (val) => {
  if (!val) return '0';
  let str = val.toString().replace(/\D/g, '');
  if (str.length > 8) str = str.slice(-8);
  const numberValue = parseInt(str, 10);
  return isNaN(numberValue) ? '0' : numberValue.toString();
};

// --- 2. SEPARATE INPUTS & CALCULATE TOTALS ---

const allItems = $input.all();
const misRetenciones = [];
const ivaCompras = [];
const ivaVentas = [];

let totalMisRet_Retencion = 0;
let totalMisRet_Percepcion = 0;
let totalIvaVentas_CR = 0;
let totalIvaCompras_Perc = 0;

for (const item of allItems) {
  const data = item.json;

  const dateVal = (data['Fecha'] || data['Fecha Ret./Perc.'] || '').toString().toUpperCase();
  if (dateVal.includes('TOTAL')) continue;

  if (data['Descripción Operación']) {
    const amount = normalizeAmount(data['Importe Ret./Perc.']);
    misRetenciones.push(data);

    const desc = data['Descripción Operación'].toUpperCase();
    if (desc.includes('RETENCION') || desc.includes('RETENCIÓN')) {
      totalMisRet_Retencion += amount;
    } else if (desc.includes('PERCEPCION') || desc.includes('PERCEPCIÓN')) {
      totalMisRet_Percepcion += amount;
    }
  } 
  else if (data['Percepciones IVA'] !== undefined) {
    const amount = normalizeAmount(data['Percepciones IVA']);
    ivaCompras.push({ ...data, _matched: false });
    totalIvaCompras_Perc += amount;
  } 
  else if (data['TC'] !== undefined || data['Total Comprobante'] !== undefined) {
    const amount = normalizeAmount(data['Total Comprobante']);
    ivaVentas.push({ ...data, _matched: false });
    totalIvaVentas_CR += amount;
  }
}

// --- 3. BUILD INDEXES WITH TOLERANCE ---

const TOLERANCE = 0.03;

const mapIvaCompras = new Map();
for (const item of ivaCompras) {
  const cuit = normalizeCUIT(item['CUIT']);
  if (!mapIvaCompras.has(cuit)) mapIvaCompras.set(cuit, []);
  mapIvaCompras.get(cuit).push(item);
}

const mapIvaVentas = new Map();
for (const item of ivaVentas) {
  const cuit = normalizeCUIT(item['CUIT']);
  if (!mapIvaVentas.has(cuit)) mapIvaVentas.set(cuit, []);
  mapIvaVentas.get(cuit).push(item);
}

// --- 4. PERFORM CROSS-CHECK WITH TOLERANCE ---

const discrepancies = [];

// A) Check: MIS RETENCIONES -> LEDGERS
for (const item of misRetenciones) {
  const desc = item['Descripción Operación'] ? item['Descripción Operación'].toUpperCase() : '';
  const date = normalizeDate(item['Fecha Ret./Perc.']);
  const cuit = normalizeCUIT(item['CUIT Agente Ret./Perc.']);
  const amount = normalizeAmount(item['Importe Ret./Perc.']);
  const invoiceStd = getStandardInvoice(item['Número Comprobante']);
  const razonSocial = item['Razón Social'] || "N/A";

  let matchFound = false;

  // CASE: RETENCION (Check vs IVA VENTAS)
  if (desc.includes('RETENCION') || desc.includes('RETENCIÓN')) {
    const potentialMatches = mapIvaVentas.get(cuit) || [];

    for (const candidate of potentialMatches) {
      if (candidate._matched) continue;

      const candidateAmount = normalizeAmount(candidate['Total Comprobante']);
      const candidateDate = normalizeDate(candidate['Fecha']);

      if (Math.abs(amount - candidateAmount) <= TOLERANCE) {
        candidate._matched = true;
        matchFound = true;

        // Check for differences
        const differences = [];
        if (date !== candidateDate) differences.push(`Fecha`);
        if (Math.abs(amount - candidateAmount) > 0.001) differences.push(`Importe`);

        // ✅ V1.4: Store ALL matches (perfect and with differences)
        discrepancies.push({
          Origen: "Mis Retenciones",
          Falta_En: differences.length > 0 ? "Coincide con diferencias" : "Coincide exactamente",
          Causa: differences.length > 0 ? "Encontrado con diferencias" : "Match perfecto",
          Razón_Social: razonSocial,
          Datos_ARCA: {
            Fecha: date,
            CUIT: cuit,
            Importe: amount,
            Comprobante: invoiceStd,
            Fuente: "ARCA"
          },
          Datos_Sistema: {
            Fecha: candidateDate,
            CUIT: cuit,
            Importe: candidateAmount,
            Comprobante: candidate['Nro. Desde'] || "N/A",
            Fuente: "IVA Ventas"
          },
          Diferencias: differences.length > 0 ? differences.join(", ") : ""
        });
        break;
      }
    }

    if (!matchFound) {
      discrepancies.push({
        Origen: "Mis Retenciones",
        Falta_En: "IVA Ventas",
        Causa: "No se encontraron los datos exactos en IVA Ventas",
        Razón_Social: razonSocial,
        Datos_Buscados: {
          Fecha: date,
          CUIT: cuit,
          Importe: amount
        }
      });
    }
  }

  // CASE: PERCEPCION (Check vs IVA COMPRAS)
  else if (desc.includes('PERCEPCION') || desc.includes('PERCEPCIÓN')) {
    const potentialMatches = mapIvaCompras.get(cuit) || [];

    for (const candidate of potentialMatches) {
      if (candidate._matched) continue;

      const candidateAmount = normalizeAmount(candidate['Percepciones IVA']);
      const candidateDate = normalizeDate(candidate['Fecha']);
      const candidateInvoice = getStandardInvoice(candidate['Nro. Desde']);

      if (Math.abs(amount - candidateAmount) <= TOLERANCE) {
        candidate._matched = true;
        matchFound = true;

        // Check for differences
        const differences = [];
        if (date !== candidateDate) differences.push(`Fecha`);
        if (invoiceStd !== candidateInvoice) differences.push(`Nro`);
        if (Math.abs(amount - candidateAmount) > 0.001) differences.push(`Importe`);

        // ✅ V1.4: Store ALL matches (perfect and with differences)
        discrepancies.push({
          Origen: "Mis Retenciones",
          Falta_En: differences.length > 0 ? "Coincide con diferencias" : "Coincide exactamente",
          Causa: differences.length > 0 ? "Encontrado con diferencias" : "Match perfecto",
          Razón_Social: razonSocial,
          Datos_ARCA: {
            Fecha: date,
