            Importe: candidateAmount,
            Comprobante: candidateInvoice,
            Fuente: "IVA Compras"
          },
          Diferencias: differences.length > 0 ? differences.join(", ") : ""
        });
        break;
      }
    }

    if (!matchFound) {
      discrepancies.push({
        Origen: "Mis Retenciones",
        Falta_En: "IVA Compras",
        Causa: "No se encontraron los datos exactos en IVA Compras",
