  '13': { TC: 'NC', Letra: 'C' },
  '19': { TC: 'FC', Letra: 'E' },
  '21': { TC: 'ND', Letra: 'E' },
  '22': { TC: 'NC', Letra: 'E' },
  '195': { TC: 'FC', Letra: 'T' },
  '196': { TC: 'ND', Letra: 'T' },
  '197': { TC: 'NC', Letra: 'T' },
};

function parseTipo(tipoStr) {
  if (!tipoStr) return { TC: 'UNKNOWN', Letra: 'UNKNOWN' };
  const match = tipoStr.toString().trim().match(/^(\d+)/);
  if (!match) return { TC: 'UNKNOWN', Letra: 'UNKNOWN' };
  return TIPO_MAP[match[1]] || { TC: 'UNKNOWN', Letra: 'UNKNOWN' };
}

const items = $input.all();

