  const tcStr = (data.TC || "").toString().toUpperCase();
  const debeSerExcluido = codigosAExcluir.some(codigo => tcStr.includes(codigo));

  return !isPlaceholder && !isExactMatch && !debeSerExcluido;
});

// Si tras el filtro no queda nada, devolver fila vacía para no romper el Excel
if (filtrados.length === 0) {
  return [{ json: {
    "Origen": "Sin excepciones encontradas", "Falta En": "-", "Causa": "-",
