// ============================================================
// IVA VENTAS - FILTRO
// v2 - Normaliza signo de Notas de Crédito (NC) a positivo.
// Las NC en el Libro IVA Ventas vienen en negativo; las forzamos
// a positivo para que coincidan con Mis Comprobantes Emitidos.
// El resto de los comprobantes conservan su signo original.
// ============================================================

function formatDate(value) {
  if (!value) return null;
  if (typeof value === 'number') {
    var date = new Date(Math.round((value - 25569) * 86400 * 1000));
    return date.toISOString().split('T')[0];
  }
  if (typeof value === 'string' && value.includes('/')) {
    var parts = value.split('/');
    if (parts.length === 3) {
      var date2 = new Date(parts[2], parts[1] - 1, parts[0]);
      return date2.toISOString().split('T')[0];
    }
  }
  return value;
}

function normalizeAmount(value) {
  if (value === undefined || value === null || value === '') return 0;
  if (typeof value === 'number') return Math.round(value * 100) / 100;
  var numValue = parseFloat(value);
  return isNaN(numValue) ? 0 : Math.round(numValue * 100) / 100;
}

var items = $input.all();
var results = [];

for (var i = 0; i < items.length; i++) {
  var d = items[i].json;

  var fechaStr = (d['Fecha'] || '').toString().toUpperCase();
  if (fechaStr.includes('TOTAL')) continue;
  if (!d['TC']) continue;

  var tc = (d['TC'] || '').toString().trim();
  var esNC = (tc === 'NC');

  // Helper: para NC fuerza el valor a positivo; el resto sin cambios.
  var amt = function (v) {
    var n = normalizeAmount(v);
    return esNC ? Math.abs(n) : n;
  };

  var otrosTributos = Math.round((
    amt(d['Percepciones IIBB']) +
    amt(d['Percepciones IVA']) +
    amt(d['Otras Percepciones'])
  ) * 100) / 100;

  results.push({
    json: {
      'Fecha':              formatDate(d['Fecha']),
      'TC':                 tc,
      'Letra':              (d['Letra'] || '').toString().trim(),
      'Pto. Vta.':          d['Pto. Vta.'],
      'Nro. Desde':         d['Nro. Desde'],
      'Razon Social':       d['Razón Social'] || 'N/A',
      'CUIT':               (d['CUIT'] || '').toString().replace(/-/g, '').trim(),
      'Neto 21%':           amt(d['Neto 21%']),
      'IVA 21%':            amt(d['IVA 21%']),
      'Neto 10.5%':         amt(d['Neto 10.5%']),
      'IVA 10.5%':          amt(d['IVA 10.5%']),
      'Neto 27%':           amt(d['Neto 27%']),
      'IVA 27%':            amt(d['IVA 27%']),
      'Neto 0%':            amt(d['Neto 0%']),
      'Neto 2.5%':          amt(d['Neto 2.5%']),
      'IVA 2.5%':           amt(d['IVA 2.5%']),
      'Neto 5%':            amt(d['Neto 5%']),
      'IVA 5%':             amt(d['IVA 5%']),
      'Importe Exento':     amt(d['Importe Exento']),
      'Importe no gravado': amt(d['Importe no gravado']),
      'Otros Tributos':     otrosTributos,
      'Total Comprobante':  amt(d['Total Comprobante']),
      '_source':            'IVA Ventas'
    }
  });
}

return results;
